```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:comment "An ontology of securities and financial instruments derived from a corpus on securities, bonds, equities, derivatives and funds." .

#################################################################
# TOP-LEVEL FINANCIAL INSTRUMENT HIERARCHY
#################################################################

fis:FinancialInstrument a owl:Class ;
    rdfs:label "financial instrument" ;
    rdfs:comment "A monetary contract between parties, per IAS 32: any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity. Reconciles two corpus statements: (1) financial instruments split into cash instruments and derivative instruments; (2) debt, equity and derivatives are described as the three main categories -- modeled here by placing DebtSecurity and EquitySecurity as kinds of Security, itself a kind of CashInstrument, alongside Derivative." .

fis:CashInstrument a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "An instrument whose value is determined directly by the markets; includes securities as well as loans and deposits that require mutual agreement to transfer." .

fis:Derivative a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    rdfs:comment "A contract whose value is derived from the performance of an underlier (asset, index, rate, currency or event). NOTE: the US SEC passage categorizes securities broadly as Debt/Equity/Derivatives, implying Derivative is a kind of Security; this conflicts with the majority view (cash vs derivative instruments) adopted here, where Derivative is disjoint from CashInstrument/Security." .

fis:CashInstrument owl:disjointWith fis:Derivative .

fis:Security a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:label "security" , "tradable financial asset" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:CashInstrument
            [ a owl:Restriction ; owl:onProperty fis:isNegotiable ; owl:hasValue true ]
        )
    ] ;
    rdfs:comment "A tradable financial asset; readily transferable and fungible, distinguishing it from loans/deposits which require mutual agreement to transfer." .

fis:Loan a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A cash instrument where borrower and lender must agree to any transfer; not readily transferable." .

fis:Deposit a owl:Class ;
    rdfs:subClassOf fis:CashInstrument ;
    rdfs:comment "A cash instrument such as a bank deposit, where transfer requires mutual agreement." .

fis:Security owl:disjointWith fis:Loan .
fis:Security owl:disjointWith fis:Deposit .

#################################################################
# SECURITY ATTRIBUTES (cross-cutting classifications)
#################################################################

fis:BearerSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isBearerInstrument ; owl:hasValue true ] ) ] ;
    rdfs:comment "Certificates entitle the holder to rights merely by holding the security; transferred by delivery." .

fis:RegisteredSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isBearerInstrument ; owl:hasValue false ] ) ] ;
    rdfs:comment "Entitles the holder to rights only if registered on a security register." .

fis:BearerSecurity owl:disjointWith fis:RegisteredSecurity .

fis:CertificatedSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isCertificated ; owl:hasValue true ] ) ] .

fis:NonCertificatedSecurity a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isCertificated ; owl:hasValue false ] ) ] ;
    rdfs:label "book-entry security" ;
    rdfs:comment "Dematerialized or 'book entry only' form." .

fis:CertificatedSecurity owl:disjointWith fis:NonCertificatedSecurity .

fis:DividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isDivided ; owl:hasValue true ] ) ] ;
    rdfs:comment "Each instrument constitutes a separate, legally distinct asset/debt." .

fis:UndividedSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isDivided ; owl:hasValue false ] ) ] ;
    rdfs:comment "The whole issue is one asset; each security is a fractional part of the undivided whole." .

fis:DividedSecurity owl:disjointWith fis:UndividedSecurity .

fis:FungibleSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Security
        [ a owl:Restriction ; owl:onProperty fis:isFungible ; owl:hasValue true ] ) ] ;
    rdfs:comment "All holdings are treated identically and are interchangeable." .

#################################################################
# DEBT / EQUITY / HYBRID SECURITY
#################################################################

fis:DebtSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "debt security" , "fixed income security" ;
    rdfs:comment "The holder is typically entitled to payment of principal and interest; includes bonds, debentures, notes and money-market instruments." .

fis:EquitySecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "equity security" ;
    rdfs:comment "A share of equity interest in an entity; a residual claim after creditors have been paid." .

fis:DebtSecurity owl:disjointWith fis:EquitySecurity .

fis:HybridSecurity a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "Combines characteristics of both debt and equity securities (e.g. preference shares, convertibles, warrants); not disjoint with DebtSecurity/EquitySecurity since e.g. preferred stock and convertible bonds belong to both." .

#################################################################
# MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:DebtSecurity
        [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:hasValue "money-market" ] ) ] ;
    rdfs:comment "Short-term debt instrument with original maturity of one year or less; highly liquid, 'near cash'." .

fis:CommercialPaper a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Unsecured promissory note with a fixed maturity usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Time deposit sold by banks/thrifts/credit unions, with a specific fixed term." .

fis:TreasuryBill a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:comment "Short-term debt obligation of a national government, maturing in three to twelve months." .

fis:RepurchaseAgreement a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price/date; corpus notes repurchase agreements 'defy categorization' into the cash/derivative matrix." .

fis:Bond owl:disjointWith fis:MoneyMarketInstrument .

#################################################################
# BOND
#################################################################

fis:Bond a owl:Class ;
    rdfs:label "bond" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:someValuesFrom xsd:date ]
            [ a owl:Restriction ; owl:onProperty fis:hasFaceValue ; owl:someValuesFrom xsd:decimal ]
        )
    ] ;
    rdfs:comment "A debt security under which the issuer owes the holder a debt and is obliged to repay principal at maturity, usually with periodic interest (coupon)." .

fis:Debenture a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond with long maturity, typically at least ten years; unsecured in common UK usage." .

fis:Note a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "A bond with shorter maturity than a debenture." .

fis:GovernmentBond a owl:Class ;
    rdfs:label "sovereign bond" , "treasury bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
    rdfs:comment "Medium or long term debt security issued by a sovereign national government." .

fis:SupranationalBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
    rdfs:comment "Debt of an international organization such as the World Bank." .

fis:MunicipalBond a owl:Class ;
    rdfs:label "muni" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
    rdfs:comment "Bond issued by state or local governments or entities they create." .

fis:CorporateBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
    rdfs:comment "Bond issued by a corporation to raise financing." .

owl:AllDisjointClasses [ owl:members ( fis:GovernmentBond fis:SupranationalBond fis:MunicipalBond fis:CorporateBond ) ] .

fis:GeneralObligationBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Secured by the full faith and credit/taxing power of the issuer." .

fis:RevenueBond a owl:Class ;
    rdfs:subClassOf fis:MunicipalBond ;
    rdfs:comment "Repayment guaranteed solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .

fis:InvestmentGradeRating a owl:Class ; rdfs:subClassOf fis:CreditRating .
fis:HighYieldRating a owl:Class ; rdfs:subClassOf fis:CreditRating ;
    rdfs:label "junk rating" .
fis:InvestmentGradeRating owl:disjointWith fis:HighYieldRating .

fis:HighYieldBond a owl:Class ;
    rdfs:label "junk bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:HighYieldRating ] ) ] ;
    rdfs:comment "Rated below investment grade; offers higher yield to compensate for higher default risk." .

fis:InvestmentGradeBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCreditRating ; owl:someValuesFrom fis:InvestmentGradeRating ] ) ] .

fis:ZeroCouponBond a owl:Class ;
    rdfs:label "discount bond" , "deep discount bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
    rdfs:comment "Pays no regular interest; issued at a substantial discount to par; face value repaid at maturity." .

fis:FixedRateBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasFixedCoupon ; owl:hasValue true ] ) ] .

fis:FloatingRateNote a owl:Class ;
    rdfs:label "floater" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasFixedCoupon ; owl:hasValue false ] ) ] ;
    rdfs:comment "Coupon varies, linked to a reference rate such as LIBOR/SOFR/Euribor." .

fis:FixedRateBond owl:disjointWith fis:FloatingRateNote .

fis:PerpetualBond a owl:Class ;
    rdfs:label "perpetuity" , "irredeemable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:isPerpetual ; owl:hasValue true ] ) ] ;
    rdfs:comment "No maturity date; principal repaid only at discretion of the borrower, if ever." .

fis:InflationIndexedBond a owl:Class ;
    rdfs:label "linker" , "index-linked bond" ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "Principal and interest payments are indexed to the level of consumer prices." .

fis:CallableBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:CallOption ] ) ] ;
    rdfs:comment "Issuer has the right to repay the bond before the maturity date." .

fis:PutableBond a owl:Class ;
    rdfs:label "retractable bond" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasEmbeddedOption ; owl:someValuesFrom fis:PutOption ] ) ] ;
    rdfs:comment "Holder has the right to force the issuer to repay the bond before maturity." .

fis:ConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
    rdfs:comment "Bond the holder can convert into a specified number of shares of the issuer's common stock; a hybrid security." .

fis:ExchangeableBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Allows exchange into shares of a corporation other than the issuer (differentia: conversion target issuer differs from bond issuer)." .

fis:MandatoryConvertibleBond a owl:Class ;
    rdfs:subClassOf fis:ConvertibleBond ;
    rdfs:comment "Forces the holder to convert into shares at maturity." .

fis:ContingentConvertibleBond a owl:Class ;
    rdfs:label "CoCo" ;
    rdfs:subClassOf fis:MandatoryConvertibleBond ;
    rdfs:comment "Automatically converts to equity if a pre-specified trigger event occurs." .

fis:BearerBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
    rdfs:comment "Official certificate issued without a named holder; claimed by whoever possesses it." .

fis:RegisteredBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
    rdfs:comment "Ownership recorded by the issuer or a transfer agent." .

fis:BookEntryBond a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] .

fis:SubordinatedBond a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:comment "Lower priority than senior bonds of the issuer in liquidation." .

fis:CoveredBond a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:Asset ]
            [ a owl:Restriction ; owl:onProperty fis:remainsOnIssuerBalanceSheet ; owl:hasValue true ]
        )
    ] ;
    rdfs:comment "Backed by cash flows from mortgages or public sector assets which remain on the issuer's balance sheet (unlike asset-backed securities)." .

fis:AssetBackedSecurity a owl:Class ;
    rdfs:label "ABS" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:Asset ]
            [ a owl:Restriction ; owl:onProperty fis:remainsOnIssuerBalanceSheet ; owl:hasValue false ]
        )
    ] ;
    rdfs:comment "Interest and principal payments backed by underlying cash flows from a pool of assets (not retained on issuer's balance sheet)." .

fis:MortgageBackedSecurity a owl:Class ;
    rdfs:label "MBS" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:Mortgage ] ) ] ;
    rdfs:comment "Asset-backed security secured by a mortgage or collection ('pool') of mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
    rdfs:label "RMBS" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .

fis:CommercialMortgageBackedSecurity a owl:Class ;
    rdfs:label "CMBS" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .

fis:CollateralizedMortgageObligation a owl:Class ;
    rdfs:label "CMO" , "pay-through bond" ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:comment "Divided into tranches with different maturities and priorities for receipt of principal." .

fis:CollateralizedDebtObligation a owl:Class ;
    rdfs:label "CDO" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
        [ a owl:Restriction ; owl:onProperty fis:isBackedBy ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
    rdfs:comment "Structured asset-backed security backed by a pool of bonds or other debt obligations, sliced into tranches." .

#################################################################
# EQUITY / STOCK
#################################################################

fis:Stock a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "share" , "equity" , "capital stock" ;
    rdfs:comment "A unit by which ownership of a corporation is divided; fractional ownership of the corporation." .

fis:CommonStock a owl:Class ;
    rdfs:label "ordinary share" , "voting share" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
        [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] ;
    rdfs:comment "Typically carries voting rights; lowest priority on dividends/liquidation among share classes." .

fis:PreferredStock a owl:Class ;
    rdfs:label "preferred shares" , "preference shares" ;
    rdfs:subClassOf fis:HybridSecurity ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Stock
        [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue false ] ) ] ;
    rdfs:comment "Generally lacks voting rights but has priority over common stock for dividends and upon liquidation; considered a hybrid instrument. NOTE: corpus states cumulative preferred shares may gain voting rights when dividends are substantially in arrears -- treated here as an exception to the default differentia." .

fis:CommonStock owl:disjointWith fis:PreferredStock .

fis:CumulativePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue true ] ) ] ;
    rdfs:comment "Unpaid dividends accumulate as a dividend in arrears until paid in full." .

fis:NoncumulativePreferredStock a owl:Class ;
    rdfs:label "straight preferred stock" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:isCumulative ; owl:hasValue false ] ) ] ;
    rdfs:comment "Passed dividends are lost if not declared." .

fis:CumulativePreferredStock owl:disjointWith fis:NoncumulativePreferredStock .

fis:ConvertiblePreferredStock a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
        [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] ;
    rdfs:comment "Preferred stock convertible into a fixed number of common shares." .

#################################################################
# DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:comment "Negotiable instrument issued by a bank representing a foreign company's publicly traded securities." .

fis:AmericanDepositaryReceipt a owl:Class ;
    rdfs:label "ADR" ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:comment "Listed and traded in the United States." .

fis:EuropeanDepositaryReceipt a owl:Class ;
    rdfs:label "EDR" ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:comment "Issued by European banks." .

fis:GlobalDepositaryReceipt a owl:Class ;
    rdfs:label "GDR" ;
    rdfs:subClassOf fis:DepositaryReceipt ;
    rdfs:comment "Issued by other (non-European, non-US) banks." .

#################################################################
# DIVIDENDS
#################################################################

fis:Dividend a owl:Class ;
    rdfs:comment "A portion of a company's profit paid to shareholders; discretionary, in contrast to a bond's contractual coupon." .

fis:CashDividend a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Dividend
        [ a owl:Restriction ; owl:onProperty fis:isPaidInCash ; owl:hasValue true ] ) ] .

fis:StockDividend a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Dividend
        [ a owl:Restriction ; owl:onProperty fis:isPaidInCash ; owl:hasValue false ] ) ] ;
    rdfs:comment "Additional shares granted instead of cash." .

fis:CashDividend owl:disjointWith fis:StockDividend .

#################################################################
# WARRANTS
#################################################################

fis:Warrant a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:isLongDated ; owl:hasValue true ] ) ] ;
    rdfs:comment "A long-dated option (maximum maturity beyond the one-year typical of short-dated options); generally traded over the counter." .

fis:EquityWarrant a owl:Class ;
    rdfs:subClassOf fis:HybridSecurity ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Warrant
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
    rdfs:comment "Option issued by a company allowing the holder to purchase a specific number of shares at a specified price within a specified time; often issued with bonds or existing equities." .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:comment "An investment fund that pools money from many investors to purchase securities." .

fis:MutualFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
    rdfs:comment "Purchased from or sold to the issuer at net asset value." .

fis:ExchangeTradedFund a owl:Class ;
    rdfs:label "ETF" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] ;
    rdfs:comment "Traded on national securities exchanges at market prices that may differ from net asset value." .

fis:MutualFund owl:disjointWith fis:ExchangeTradedFund .

fis:MoneyMarketFund a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:MoneyMarketInstrument ] ) ] .

fis:BondFund a owl:Class ;
    rdfs:label "income fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:DebtSecurity ] ) ] .

fis:EquityFund a owl:Class ;
    rdfs:label "stock fund" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:InvestmentFund
        [ a owl:Restriction ; owl:onProperty fis:hasPortfolio ; owl:someValuesFrom fis:EquitySecurity ] ) ] .

fis:HedgeFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "Pools money like a mutual fund but with fewer investor-protection regulations and more flexible/speculative strategies." .

fis:IndexFund a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:comment "Passively managed fund designed to track the performance of a market index." .

#################################################################
# DERIVATIVES
#################################################################

fis:LockProduct a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isObligatory ; owl:hasValue true ] ) ] ;
    rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .

fis:Option a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isObligatory ; owl:hasValue false ] ) ] ;
    rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell the underlying at a specified strike price on or before a specified date." .

fis:LockProduct owl:disjointWith fis:Option .

fis:Forward a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
    rdfs:comment "Non-standardized contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] ;
    rdfs:comment "Standardized contract written by a clearing house that operates an exchange where the contract can be bought and sold." .

fis:Swap a owl:Class ;
    rdfs:subClassOf fis:LockProduct ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:LockProduct
        [ a owl:Restriction ; owl:onProperty fis:hasNotionalAmount ; owl:someValuesFrom xsd:decimal ] ) ] ;
    rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another, calculated over a notional principal amount that itself is not exchanged." .

owl:AllDisjointClasses [ owl:members ( fis:Forward fis:Future fis:Swap ) ] .

fis:ExchangeTradedDerivative a owl:Class ;
    rdfs:label "ETD" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] .

fis:OTCDerivative a owl:Class ;
    rdfs:label "over-the-counter derivative" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Derivative
        [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] ;
    rdfs:comment "Privately negotiated directly between two parties without going through an exchange." .

fis:ExchangeTradedDerivative owl:disjointWith fis:OTCDerivative .

#################################################################
# OPTIONS
#################################################################

fis:CallOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:isCallOption ; owl:hasValue true ] ) ] ;
    rdfs:comment "The right, not the obligation, to buy an asset at a fixed strike price." .

fis:PutOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:isCallOption ; owl:hasValue false ] ) ] ;
    rdfs:comment "The right, not the obligation, to sell an asset at a fixed strike price." .

fis:CallOption owl:disjointWith fis:PutOption .

fis:AmericanOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] ;
    rdfs:comment "May be exercised on any trading day on or before expiration." .

fis:EuropeanOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] ;
    rdfs:comment "May only be exercised on the expiry date." .

fis:BermudanOption a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Option
        [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] ;
    rdfs:comment "May be exercised only on specified dates on or before expiration." .

owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

#################################################################
# SWAPS
#################################################################

fis:InterestRateSwap a owl:Class ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRate ] ) ] .

fis:CurrencySwap a owl:Class ;
    rdfs:label "cross-currency swap" ;
    owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Swap
        [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] .

fis:CreditDefaultSwap a owl:Class ;
    rdfs:label "CDS" ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf ( fis:Swap
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtObligation ]
            [ a owl:Restriction ; owl:onProperty fis:providesProtectionAgainst ; owl:someValuesFrom fis:CreditEvent ]
        )
    ] ;
    rdfs:comment "Seller compensates buyer in the event of a loan default or other credit event on a reference debt obligation." .

owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap ) ] .

#################################################################
# ISSUERS, HOLDERS, UNDERLIERS, ASSETS
#################################################################

fis:Issuer a owl:Class ;
    rdfs:comment "The company or other entity issuing a security." .

fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:LocalGovernment a owl:Class ; rdfs:subClassOf fis:Issuer ;
    rdfs:comment "State, provincial, territorial, municipal or other governmental unit below sovereign level." .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:FinancialInstitution a owl:Class ; rdfs:subClassOf fis:Issuer .

owl:AllDisjointClasses [ owl:members (
    fis:Corporation fis:SovereignGovernment fis:LocalGovernment
    fis:SupranationalOrganization fis:FinancialInstitution ) ] .

fis:Holder a owl:Class ;
    rdfs:comment "The party entitled to rights under a security (creditor, shareholder, etc.)." .

fis:Underlier a owl:Class ;
    rdfs:label "underlying asset" ;
    rdfs:comment "The asset, index, rate, currency or event upon which a derivative's value depends." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:MarketIndex a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:CreditEvent a owl:Class ; rdfs:subClassOf fis:Underlier ;
    rdfs:comment "An event such as default triggering compensation under a credit derivative." .

fis:Asset a owl:Class ;
    rdfs:comment "A resource that can back or collateralize a security." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:ResidentialMortgage owl:disjointWith fis:CommercialMortgage .

fis:DebtObligation a owl:Class ;
    rdfs:subClassOf fis:Asset , fis:Underlier ;
    rdfs:comment "A bond, loan or other debt instrument that can back an ABS/CDO or serve as reference obligation of a CDS." .

fis:CreditRating a owl:Class ;
    rdfs:comment "A grade assigned by a credit rating agency indicating overall credit quality." .

#################################################################
# RISK
#################################################################

fis:Risk a owl:Class ;
    rdfs:comment "A category of risk to which holders of a financial instrument are exposed." .

fis:CreditRisk a owl:Class ; rdfs:subClassOf fis:Risk ;
    rdfs:comment "Risk that the issuer will default by failing to pay interest and/or repay principal." .
fis:DefaultRisk a owl:Class ; rdfs:subClassOf fis:CreditRisk .
fis:InterestRateRisk a owl:Class ; rdfs:subClassOf fis:Risk ;
    rdfs:comment "Market price falls when prevailing interest rates rise." .
fis:LiquidityRisk a owl:Class ; rdfs:subClassOf fis:Risk .
fis:ReinvestmentRisk a owl:Class ; rdfs:subClassOf fis:Risk ;
    rdfs:comment "Risk that a holder must reinvest proceeds (e.g. of a called bond) at a lower rate." .
fis:InflationRisk a owl:Class ; rdfs:subClassOf fis:Risk .
fis:CurrencyRisk a owl:Class ; rdfs:subClassOf fis:Risk ;
    rdfs:label "exchange rate risk" .
fis:SovereignRisk a owl:Class ; rdfs:subClassOf fis:Risk .
fis:CallRisk a owl:Class ; rdfs:subClassOf fis:Risk ;
    rdfs:comment "Risk that an issuer will redeem a callable bond prior to maturity." .
fis:CounterpartyRisk a owl:Class ; rdfs:subClassOf fis:Risk .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Issuer .

fis:isIssuerOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasIssuer ;
    rdfs:domain fis:Issuer ;
    rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
    rdfs:domain fis:Security ;
    rdfs:range fis:Holder .

fis:isHolderOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasHolder ;
    rdfs:domain fis:Holder ;
    rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:Underlier .

fis:isUnderlyingOf a owl:ObjectProperty ;
    owl:inverseOf fis:hasUnderlying ;
    rdfs:domain fis:Underlier ;
    rdfs:range fis:Derivative .

fis:hasEmbeddedOption a owl:ObjectProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Option .

fis:hasConversionTarget a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:domain fis:HybridSecurity ;
    rdfs:range fis:EquitySecurity .

fis:isBackedBy a owl:ObjectProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range fis:Asset .

fis:providesProtectionAgainst a owl:ObjectProperty ;
    rdfs:domain fis:CreditDefaultSwap ;
    rdfs:range fis:CreditEvent .

fis:hasCreditRating a owl:ObjectProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range fis:CreditRating .

fis:hasPortfolio a owl:ObjectProperty ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:Security .

fis:hasDividend a owl:ObjectProperty ;
    rdfs:domain fis:EquitySecurity ;
    rdfs:range fis:Dividend .

fis:hasRiskExposure a owl:ObjectProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Risk .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:date ;
    rdfs:comment "The date on which the issuer repays the nominal amount and the term ends." .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "par value" , "principal" , "nominal amount" ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal .

fis:hasCouponRate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal .

fis:hasYieldToMaturity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "redemption yield" ;
    rdfs:domain fis:Bond ;
    rdfs:range xsd:decimal .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "exercise price" ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasPremium a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Swap ;
    rdfs:range xsd:decimal .

fis:isStandardized a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean .

fis:isExchangeTraded a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range xsd:boolean .

fis:isObligatory a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:boolean ;
    rdfs:comment "True if both parties must perform (lock product); false if only the seller is obligated (option)." .

fis:isNegotiable a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:CashInstrument ;
    rdfs:range xsd:boolean .

fis:isBearerInstrument a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean .

fis:isCertificated a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean .

fis:isDivided a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean .

fis:isFungible a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:boolean .

fis:hasTermCategory a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:string ;
    rdfs:comment "One of: money-market, short-term, medium-term, long-term, perpetual." .

fis:hasFixedCoupon a owl:DatatypeProperty , owl:FunctionalProperty ;
