fis:isCumulative a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:PreferredStock ;
    rdfs:range xsd:boolean .

fis:isCallOption a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:domain fis:Option ;
