```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology of financial instruments, securities, derivatives and funds, built strictly from the supplied corpus." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

fis:FinancialInstrument a owl:Class ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties, which can be created, traded, modified and settled; per IAS 32/39, any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity." .

fis:Underlier a owl:Class ;
  rdfs:label "underlier" ;
  rdfs:comment "The asset, rate, index or event upon which a derivative's value is based; an underlying can be a commodity, a financial instrument, a price index, a currency, or an interest rate." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "Instruments whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:DerivativeInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument, fis:Underlier ;
  rdfs:comment "A contract whose value is derived from the performance of an underlier (commodity, financial instrument, index, currency or interest rate); has four elements: an underlier, a future act, a price and a future date." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:CashInstrument fis:DerivativeInstrument ) .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Underlier .
fis:Index a owl:Class ; rdfs:subClassOf fis:Underlier ;
  rdfs:comment "A price index, e.g. a stock market index." .
fis:InterestRate a owl:Class ; rdfs:subClassOf fis:Underlier .

fis:FinancialInstrument rdfs:subClassOf fis:Underlier .

#################################################################
# SECURITY (general)
#################################################################

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" ;
  rdfs:comment "A tradable financial asset; a negotiable and fungible financial contract entitling the holder to investment returns. US securities law broadly categorizes securities into debt securities, equity securities and derivatives; however, this corpus elsewhere states that derivatives are one of three main categories of financial instruments alongside equity and debt (implying derivatives are not securities). This ontology follows the latter, more general, statement and treats DerivativeInstrument as a sibling of Security, noting the conflicting US SEC characterization here." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .
fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Loan .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .

[] a owl:AllDisjointClasses ; owl:members ( fis:Security fis:Loan fis:Deposit ) .
[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) .

# Certification / form of security
fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A security represented by a physical certificate." .
fis:NonCertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "book-entry security" ;
  rdfs:comment "A security with no paper certificate; electronic / dematerialized / 'book entry only' form." .
fis:BearerSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:comment "A certificate that entitles the holder to rights under the security merely by holding it." .
fis:RegisteredSecurity a owl:Class ; rdfs:subClassOf fis:CertificatedSecurity ;
  rdfs:comment "A certificate that entitles the holder to rights only if they appear on a security register maintained by the issuer or an intermediary." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CertificatedSecurity fis:NonCertificatedSecurity ) .
[] a owl:AllDisjointClasses ; owl:members ( fis:BearerSecurity fis:RegisteredSecurity ) .

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A security giving the holder entitlement to payment of principal and interest plus other contractual rights; generally issued for a fixed term and redeemable by the issuer at the end of that term." .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A share of equity interest in an entity such as the capital stock of a company, trust or partnership; a residual claim after creditors are paid, generally entitling the holder to pro rata control and to profits." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "A security combining characteristics of both debt and equity securities." .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity ) .

fis:Share a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "A unit of account for many different financial things, including stocks, mutual funds, limited partnerships and REITs." .

#################################################################
# PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Issuer ;
  rdfs:comment "The company or other entity issuing the security is called the issuer." .
fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:FinancialInstrument .

fis:hasHolder a owl:ObjectProperty ; rdfs:domain fis:Security ; rdfs:range fis:Investor .
fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty ; rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Underlier ;
  rdfs:comment "Relates a derivative or asset-backed instrument to the asset(s), index, rate or pool from which its value or cash flow is derived." .
fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Underlier ; rdfs:range fis:FinancialInstrument .

fis:hasUnderwriter a owl:ObjectProperty ; rdfs:domain fis:Bond ; rdfs:range fis:Underwriter .
fis:isUnderwriterOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderwriter ;
  rdfs:domain fis:Underwriter ; rdfs:range fis:Bond .

fis:hasPrincipalInvestment a owl:ObjectProperty ; rdfs:domain fis:InvestmentFund ; rdfs:range fis:Security ;
  rdfs:comment "The principal class of securities held by a fund's portfolio." .
fis:isPrincipalInvestmentOf a owl:ObjectProperty ; owl:inverseOf fis:hasPrincipalInvestment ;
  rdfs:domain fis:Security ; rdfs:range fis:InvestmentFund .

fis:hasTradingVenue a owl:ObjectProperty ; rdfs:domain fis:Security ; rdfs:range fis:Market .
fis:isTradingVenueOf a owl:ObjectProperty ; owl:inverseOf fis:hasTradingVenue ;
  rdfs:domain fis:Market ; rdfs:range fis:Security .

fis:hasClearingHouse a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Future ; rdfs:range fis:ClearingHouse ;
  rdfs:comment "A futures contract is written by a clearing house that operates an exchange where the contract can be bought and sold." .
fis:isClearingHouseOf a owl:ObjectProperty ; owl:inverseOf fis:hasClearingHouse ;
  rdfs:domain fis:ClearingHouse ; rdfs:range fis:Future .

fis:hasAcquisitionSource a owl:ObjectProperty ; rdfs:domain fis:Security ; rdfs:range fis:MarketParticipant ;
  rdfs:comment "The party from which a restricted/control security was acquired (the issuer or an affiliate of the issuer)." .
fis:isAcquisitionSourceOf a owl:ObjectProperty ; owl:inverseOf fis:hasAcquisitionSource ;
  rdfs:domain fis:MarketParticipant ; rdfs:range fis:Security .

fis:hasIndenture a owl:ObjectProperty, owl:FunctionalProperty ; rdfs:domain fis:Bond ; rdfs:range fis:Indenture ;
  rdfs:comment "An indenture is a formal debt agreement that establishes the terms of a bond issue." .
fis:isIndentureOf a owl:ObjectProperty ; owl:inverseOf fis:hasIndenture ;
  rdfs:domain fis:Indenture ; rdfs:range fis:Bond .

fis:hasCovenant a owl:ObjectProperty ; rdfs:domain fis:Indenture ; rdfs:range fis:Covenant ;
  rdfs:comment "Covenants are the clauses of an indenture, specifying rights of bondholders and duties of issuers." .
fis:isCovenantOf a owl:ObjectProperty ; owl:inverseOf fis:hasCovenant ;
  rdfs:domain fis:Covenant ; rdfs:range fis:Indenture .

fis:hasCollateral a owl:ObjectProperty ; rdfs:domain fis:CollateralArrangement ; rdfs:range fis:Underlier .
fis:isCollateralOf a owl:ObjectProperty ; owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Underlier ; rdfs:range fis:CollateralArrangement .

# Datatype properties
fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:date .
fis:hasMaturityInDays a owl:DatatypeProperty ; rdfs:domain fis:DebtSecurity ; rdfs:range xsd:integer .
fis:hasMaturityInYears a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:integer .
fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "Nominal, principal, par, or face amount: the amount on which the issuer pays interest and which must be repaid at the end of the term." .
fis:hasCouponRate a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The coupon is the interest rate that the issuer pays to the holder." .
fis:hasYieldToMaturity a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:decimal .
fis:hasIssuePrice a owl:DatatypeProperty ; rdfs:domain fis:Security ; rdfs:range xsd:decimal .
fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain fis:Option ; rdfs:range xsd:decimal .
fis:hasExpirationDate a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain fis:Option ; rdfs:range xsd:date .
fis:hasPremium a owl:DatatypeProperty ; rdfs:domain fis:Option ; rdfs:range xsd:decimal .
fis:hasDeliveryDate a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain fis:LockProduct ; rdfs:range xsd:date .
fis:hasDeliveryPrice a owl:DatatypeProperty ; rdfs:domain fis:LockProduct ; rdfs:range xsd:decimal .
fis:hasNotionalAmount a owl:DatatypeProperty ; rdfs:domain fis:Swap ; rdfs:range xsd:decimal .
fis:hasCreditRating a owl:DatatypeProperty ; rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string .
fis:isCallable a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:boolean .
fis:isPutable a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:boolean .
fis:isConvertible a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:boolean .
fis:isSenior a owl:DatatypeProperty ; rdfs:domain fis:Bond ; rdfs:range xsd:boolean .
fis:isSecured a owl:DatatypeProperty ; rdfs:domain fis:DebtSecurity ; rdfs:range xsd:boolean .
fis:isFungible a owl:DatatypeProperty ; rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:comment "In a fungible security, all holdings of the security are treated identically and are interchangeable." .
fis:isDivided a owl:DatatypeProperty ; rdfs:domain fis:Security ; rdfs:range xsd:boolean ;
  rdfs:comment "Each divided security constitutes a separate asset; undivided securities form one single asset of which each security is a fractional part." .
fis:isStandardized a owl:DatatypeProperty ; rdfs:domain fis:DerivativeInstrument ; rdfs:range xsd:boolean .
fis:hasVotingRight a owl:DatatypeProperty ; rdfs:domain fis:Stock ; rdfs:range xsd:boolean .
fis:hasDividendPriority a owl:DatatypeProperty ; rdfs:domain fis:Stock ; rdfs:range xsd:boolean .
fis:hasOptionRight a owl:DatatypeProperty ; rdfs:domain fis:Option ; rdfs:range xsd:string .
fis:hasExerciseStyle a owl:DatatypeProperty ; rdfs:domain fis:Option ; rdfs:range xsd:string .
fis:hasConversionRatio a owl:DatatypeProperty ; rdfs:domain fis:ConvertibleBond ; rdfs:range xsd:decimal .

#################################################################
# BOND / DEBT SECURITY TAXONOMY
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A security under which the issuer owes the holder a debt and is obliged to provide cash flow, usually repaying principal at maturity plus interest (coupon)." .

fis:MoneyMarketInstrument a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:DebtSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityInDays ;
        owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
          owl:withRestrictions ( [ xsd:maxInclusive 365 ] ) ] ]
  ) ] ;
  rdfs:comment "Short-term debt instruments with original maturities of one year or less; highly liquid, sometimes called 'near cash'." .

fis:Debenture a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:isSecured ; owl:hasValue false ]
  ) ] ;
  rdfs:comment "An unsecured bond with only a general claim on the issuer's assets; typically a long maturity of at least ten years." .

fis:Note a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A debt security with a shorter maturity than a debenture." .

# By issuer
fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "sovereign bond" ;
  rdfs:comment "Medium or long term debt security issued by a sovereign national government." .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ] ) ] ;
  rdfs:label "muni" ;
  rdfs:comment "A bond issued by a local authority or subdivision within a country." .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
  rdfs:label "supra" ;
  rdfs:comment "A bond issued by a supranational organization such as the World Bank." .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Represents the debt of commercial or industrial entities, issued to fund operations, M&A or expansion." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond fis:CorporateBond ) .

# By maturity length
fis:ShortTermBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasMaturityInYears ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ; owl:withRestrictions ( [ xsd:maxExclusive 5 ] ) ] ] ) ] .
fis:MediumTermBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasMaturityInYears ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ; owl:withRestrictions ( [ xsd:minInclusive 5 ] [ xsd:maxInclusive 15 ] ) ] ] ) ] .
fis:LongTermBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasMaturityInYears ;
      owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ; owl:withRestrictions ( [ xsd:minExclusive 15 ] ) ] ] ) ] .

[] a owl:AllDisjointClasses ; owl:members ( fis:ShortTermBond fis:MediumTermBond fis:LongTermBond ) .

fis:PerpetualBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A perpetuity: a bond with no maturity date, also called an irredeemable bond." .

# By coupon type
fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Variable coupon linked to a reference rate of interest such as LIBOR/SOFR or Euribor." .
fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasCouponRate ; owl:hasValue "0.0"^^xsd:decimal ] ) ] ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par, with the full principal paid at maturity." .
fis:StripBond a owl:Class ; rdfs:subClassOf fis:ZeroCouponBond ;
  rdfs:comment "Created by separating ('stripping') the coupons from the principal of a coupon bond." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Principal amount and interest payments are indexed to the level of consumer prices (linkers / index-linked bonds / TIPS)." .

[] a owl:AllDisjointClasses ; owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) .

# By optionality
fis:CallableBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isCallable ; owl:hasValue true ] ) ] ;
  rdfs:comment "Gives the issuer the right to repay the bond before the maturity date on the call dates." .
fis:PutableBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isPutable ; owl:hasValue true ] ) ] ;
  rdfs:label "retractable bond" ;
  rdfs:comment "Gives the holder the right to force the issuer to repay the bond before the maturity date." .

fis:ConvertibleBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isConvertible ; owl:hasValue true ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:comment "Lets the bondholder exchange the bond for a specified number of shares of the issuer's common stock; a hybrid security combining debt and equity features." .
fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .
fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:PackagedConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:label "bond + option structure" ;
  rdfs:comment "A straight bond and a call option/warrant wrapped together, tradable as separate legs." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
  rdfs:label "CoCo" ;
  rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs." .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity, settled in cash." .

# By form
fis:BearerBond a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] ;
  rdfs:comment "An official certificate issued without a named holder; claimable by whoever possesses it." .
fis:RegisteredBond a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] ;
  rdfs:comment "Ownership is recorded by the issuer or a transfer agent." .
fis:BookEntryBond a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] ;
  rdfs:comment "A bond that does not have a paper certificate." .

# By seniority / credit quality
fis:SeniorBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isSenior ; owl:hasValue true ] ) ] .
fis:SubordinatedBond a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:isSenior ; owl:hasValue false ] ) ] ;
  rdfs:comment "Has lower priority than senior bonds of the issuer in case of liquidation." .

fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "high grade bond" .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "junk bond" ;
  rdfs:comment "Rated below investment grade; investors expect a higher yield to compensate for higher default risk." .

[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) .

# Asset-backed family
fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Bond
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Loan ] ) ] ;
  rdfs:comment "A bond whose interest and principal payments are backed by underlying cash flows from a pool of other assets (e.g. consumer loans, leases, receivables)." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:comment "Secured by a mortgage or a pool of mortgages." .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
  rdfs:label "RMBS" .
fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:MortgageBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
  rdfs:label "CMBS" .

[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgageBackedSecurity fis:CommercialMortgageBackedSecurity ) .

fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Allocates cash flows from the underlying pool to security holders on a pro rata basis." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "pay-through bond" ;
  rdfs:comment "A debt obligation collateralized by the assets it owns, divided into classes with different maturities and payment priorities." .

[] a owl:AllDisjointClasses ; owl:members ( fis:PassThroughSecurity fis:CollateralizedMortgageObligation ) .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "SMBS" .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
  rdfs:label "IO" ; rdfs:comment "Cash flows backed by the interest component of mortgage payments." .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
  rdfs:label "PO" ; rdfs:comment "Cash flows backed by the principal repayment component of mortgage payments." .

[] a owl:AllDisjointClasses ; owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:AssetBackedSecurity
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
  rdfs:label "CDO" ;
  rdfs:comment "Backed by a pool of debt obligations, often other asset-backed securities, sliced into tranches by seniority." .

fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets; unlike asset-backed securities, the assets remain on the issuer's balance sheet." ;
  owl:disjointWith fis:AssetBackedSecurity .

# By purpose
fis:WarBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issuer redeems randomly selected individual bonds within the issue, some at higher than face value." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer and usually the issuer's taxing power." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repayment guaranteed solely from revenues generated by a specified revenue-generating entity; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments of properties within the issuer's boundaries." .

[] a owl:AllDisjointClasses ; owl:members ( fis:GeneralObligationBond fis:RevenueBond ) .

# Money market instruments
fis:CommercialPaper a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf (
      fis:MoneyMarketInstrument
      [ a owl:Restriction ; owl:onProperty fis:isSecured ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityInDays ;
        owl:someValuesFrom [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
          owl:withRestrictions ( [ xsd:maxInclusive 270 ] ) ] ]
  ) ] ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "CD" ;
  rdfs:comment "A time deposit sold by banks, thrift institutions and credit unions, with a specific fixed term." .

fis:TreasuryBill a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:MoneyMarketInstrument fis:ZeroCouponBond
    [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:comment "Zero-coupon government bonds that mature in one year or less, bought at a discount to par." .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:label "repo" ;
  rdfs:comment "Short-term loan arranged by selling securities to an investor with an agreement to repurchase them at a fixed price on a fixed date." .

#################################################################
# EQUITY SECURITY TAXONOMY
#################################################################

fis:Stock a owl:Class ; rdfs:subClassOf fis:EquitySecurity, fis:Share ;
  rdfs:comment "Consists of all the shares by which ownership of a corporation is divided; a stockholder is a fractional owner of the corporation." .

fis:CommonStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasVotingRight ; owl:hasValue true ] ) ] ;
  rdfs:label "ordinary share" ;
  rdfs:comment "Carries voting rights exercised in corporate decisions; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Stock
    [ a owl:Restriction ; owl:onProperty fis:hasDividendPriority ; owl:hasValue true ] ) ] ;
  rdfs:subClassOf fis:HybridSecurity ;
  rdfs:label "preference share" ;
  rdfs:comment "Senior to common stock but subordinate to bonds; has priority on dividends and liquidation but typically no voting rights; a hybrid instrument." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate as a dividend in arrears, to be paid before any common dividend." .
fis:NoncumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "straight preferred stock" ;
  rdfs:comment "Any passed dividend is lost if not declared." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CumulativePreferredStock fis:NoncumulativePreferredStock ) .

fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Includes the ability of the holder to convert preferred shares into a fixed number of common shares." .
fis:CallablePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Carries a call provision enabling the issuing corporation to repurchase the share at its discretion." .

fis:FundShare a owl:Class ; rdfs:subClassOf fis:Share ;
  rdfs:comment "A unit of ownership issued by an investment fund, representing a proportional interest in the fund's portfolio." .

fis:RestrictedSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasAcquisitionSource ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:comment "Acquired in unregistered form directly from the issuing company (SEC Rule 144)." .
fis:ControlSecurity a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Security
    [ a owl:Restriction ; owl:onProperty fis:hasAcquisitionSource ; owl:someValuesFrom fis:Affiliate ] ) ] ;
  rdfs:comment "Acquired in unregistered form from an affiliate of the issuer (SEC Rule 144)." .

[] a owl:AllDisjointClasses ; owl:members ( fis:RestrictedSecurity fis:ControlSecurity ) .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "DR" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local exchange." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "ADR" ; rdfs:comment "Listed and traded in the United States." .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "EDR" ; rdfs:comment "Issued by European banks." .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "GDR" ; rdfs:comment "Issued by other (non-US, non-European) banks." .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) .

#################################################################
# DERIVATIVE TAXONOMY
#################################################################

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under the terms specified." .

[] a owl:AllDisjointClasses ; owl:members ( fis:LockProduct fis:OptionProduct ) .

fis:Forward a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:LockProduct
    [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
  rdfs:comment "A non-standardized, over-the-counter contract between two parties to buy or sell an asset at a specified future time at a price agreed today." .

fis:ForwardRateAgreement a owl:Class ; rdfs:subClassOf fis:Forward ;
  rdfs:label "FRA" ;
  rdfs:comment "An agreement to pay a fixed rate of interest on a notional amount of money for a period beginning in the future." .

fis:Future a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:LockProduct
    [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ]
    [ a owl:Restriction ; owl:onProperty fis:hasClearingHouse ; owl:someValuesFrom fis:ClearingHouse ] ) ] ;
  rdfs:comment "A standardized contract to buy or sell a specified asset at a price agreed today, written by a clearing house and traded on an exchange." .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows of one financial instrument for those of another, calculated over a notional principal amount." .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date." .

[] a owl:AllDisjointClasses ; owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) .

fis:CallOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "buy" ] ) ] ;
  rdfs:comment "The right, not obligation, to buy the underlying at the strike price." .
fis:PutOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasOptionRight ; owl:hasValue "sell" ] ) ] ;
  rdfs:comment "The right, not obligation, to sell the underlying at the strike price." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CallOption fis:PutOption ) .

fis:AmericanOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "american" ] ) ] ;
  rdfs:comment "May be exercised on any trading day on or before expiration." .
fis:EuropeanOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "european" ] ) ] ;
  rdfs:comment "May only be exercised on expiry." .
fis:BermudanOption a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( fis:Option
    [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "bermudan" ] ) ] ;
  rdfs:comment "May be exercised only on specified dates on or before expiration." .

[] a owl:AllDisjointClasses ; owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over some preset time period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying security's price must pass a certain level or 'barrier' before it can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An all-or-nothing option that pays the full amount if the underlying meets a defined condition at expiration." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Any option with complex financial structures beyond vanilla American/European options." .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "A long-dated option, generally traded over the counter, with a maximum maturity period beyond one year." .
fis:StockOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "An option whose underlying is a stock." .

fis:EquityWarrant a owl:Class ; rdfs:subClassOf fis:Warrant, fis:HybridSecurity ;
  rdfs:comment "Issued by a company, allowing the holder to purchase a specific number of its shares at a specified price within a specified time; often issued with bonds or existing equities." .

fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap, fis:CreditDerivative ;
  rdfs:label "CDS" ;
  rdfs:comment "The seller compensates the buyer in the event of a loan default or other credit event, in exchange for periodic payments." .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .

[] a owl:AllDisjointClasses ;
  owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CreditDefaultSwap fis:CommoditySwap fis:EquitySwap ) .

fis:CreditDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:comment "A contract that transfers credit risk from a protection buyer to a credit protection seller." .

fis:ExchangeTradedDerivative a owl:Class ; rdfs:subClassOf fis:DerivativeInstrument ;
  rdfs:label "ETD" .
